INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 26, 'theory', 'Квиз: Системные вызовы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 0, 'Вызов read на сокете запросил 4096 байт, а вернул 3. Что это значит?', '["Произошла ошибка, причину надо смотреть в errno", "Это допустимый короткий результат: читают дальше, пока не наберут нужное или не получат 0", "Файл закончился", "Собеседник закрыл сокет"]', 1, 'Короткий read — не ошибка: каналы, терминалы и сокеты отдают столько, сколько уже есть. Конец файла и закрытие с другой стороны сообщает именно ноль, а ошибку — минус один.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 1, 'Что означает строка strace: read(3, "", 4096) = 0?', '["Ошибка чтения", "Вызов прервали сигналом, его надо повторить", "Ядро пока ничего не успело прочитать", "Достигнут конец файла: больше данных не будет"]', 3, 'Ноль от read — конец файла (для канала или сокета — закрытие с другой стороны). Ошибка выглядела бы как −1 с именем errno, а прерывание — как −1 EINTR.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 2, 'Код после неудачного read вызывает close и возвращает −1. Почему вызывающий может получить неверный errno?', '["close, даже успешный, вправе изменить errno: значение нужно скопировать сразу после сбоя и восстановить", "У каждой функции своя копия errno", "errno обнуляется при каждом return", "errno общая для всех потоков, поэтому возникает гонка"]', 0, 'errno значима только сразу после вызова, сообщившего об ошибке; успешный вызов вправе её менять, а нулём библиотека её не сбрасывает. Поэтому значение сохраняют и восстанавливают после очистки. errno при этом своя у каждого потока.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 3, 'Процесс закрыл дескриптор 0 и сразу вызвал open. Какой номер вернётся?', '["Следующий после наибольшего открытого", "Случайный свободный", "0: выдаётся наименьший свободный номер", "Всегда 3"]', 2, 'Открывающие вызовы отдают наименьший свободный дескриптор. На этом правиле держится перенаправление: закрыли 0 и открыли файл, он стал стандартным вводом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 26, 4, 'close вернул −1 с EINTR. Что делать на Linux?', '["Повторять close, пока он не вернёт 0", "Не повторять: на Linux дескриптор уже закрыт, а повтор может закрыть чужой", "Считать, что все данные надёжно записаны", "Перезапустить процесс"]', 1, 'По справочнику на Linux ядро освобождает дескриптор в любом случае, поэтому повторный close рискует закрыть дескриптор, уже выданный другому потоку. Надёжность записи проверяют через fsync до закрытия.');
